def rnd_sent(maxv):
    # sorted disjoint nonadjacent
    pts=sorted(random.sample(range(0,maxv+1), k=min(random.randint(0,3), maxv+1))) if maxv+1>=1 else []
    r=[]; i=0
    while i < len(pts):
        lo=pts[i]; hi=lo+random.randint(0,2)
